import java.util.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;import java.nio.file.*;
public final class PlaymogoPlayerCheck {
 public static void main(String[] args)throws Exception{
  JSONObject f=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getJSONArray("fixtures").getJSONObject(Integer.parseInt(args[1]));NativeHttp.CURRENT.set(new NativeHttp.Session(30000));Object player=null,thread=null;Class<?> type=Class.forName("android.media.MediaPlayer");
  try{
   NativeCatalog.Candidate selected=null;for(NativeCatalog.Candidate c:new DozaCatalog().discover(f.getJSONObject("data")))if(c.host.equals("Playmogo")){selected=c;break;}if(selected==null)throw new AssertionError("No Playmogo candidate");ResolvedStream stream=RoDubbedProvider.resolve(selected);Object link=RoDubbedProvider.makeLink(stream);final Map headers=(Map)link.getClass().getMethod("getHeaders").invoke(link);if(headers.containsKey("Origin"))throw new AssertionError("Incorrect native playback header");
   Class<?> handlerThread=Class.forName("android.os.HandlerThread"),looper=Class.forName("android.os.Looper"),handler=Class.forName("android.os.Handler");thread=handlerThread.getConstructor(String.class).newInstance("Playmogo-playback-test");handlerThread.getMethod("start").invoke(thread);Object eventLoop=handlerThread.getMethod("getLooper").invoke(thread),eventHandler=handler.getConstructor(looper).newInstance(eventLoop);
   final AtomicReference<Object> created=new AtomicReference<>();final AtomicReference<Throwable> problem=new AtomicReference<>();final CountDownLatch prepared=new CountDownLatch(1),seeked=new CountDownLatch(1);final Class<?> seekListener=Class.forName("android.media.MediaPlayer$OnSeekCompleteListener");
   final Object listener=Proxy.newProxyInstance(seekListener.getClassLoader(),new Class[]{seekListener},(proxy,method,values)->{if(method.getName().equals("onSeekComplete"))seeked.countDown();return null;});
   handler.getMethod("post",Runnable.class).invoke(eventHandler,new Runnable(){public void run(){try{Object p=type.getConstructor().newInstance();created.set(p);type.getMethod("setVolume",float.class,float.class).invoke(p,0f,0f);type.getMethod("setOnSeekCompleteListener",seekListener).invoke(p,listener);type.getMethod("setDataSource",String.class,Map.class).invoke(p,stream.url,headers);type.getMethod("prepare").invoke(p);}catch(Throwable e){problem.set(e);}finally{prepared.countDown();}}});
   if(!prepared.await(20,TimeUnit.SECONDS))throw new AssertionError("Player prepare timed out");if(problem.get()!=null)throw problem.get();player=created.get();int duration=(Integer)type.getMethod("getDuration").invoke(player);if(duration<90000)throw new AssertionError("Error clip");
   type.getMethod("seekTo",int.class).invoke(player,60000);if(!seeked.await(12,TimeUnit.SECONDS))throw new AssertionError("Seek did not complete");type.getMethod("start").invoke(player);Thread.sleep(500);int before=(Integer)type.getMethod("getCurrentPosition").invoke(player);Thread.sleep(2200);int position=(Integer)type.getMethod("getCurrentPosition").invoke(player),width=(Integer)type.getMethod("getVideoWidth").invoke(player),height=(Integer)type.getMethod("getVideoHeight").invoke(player);boolean playing=(Boolean)type.getMethod("isPlaying").invoke(player);if(!playing||position-before<1000||position<30000||width<=0||height<=0)throw new AssertionError("Playback did not advance: "+before+" -> "+position+" "+playing);
   System.out.println(new JSONObject().put("title",f.getString("title")).put("pass",true).put("player","Android MediaPlayer, muted").put("seekCompleted",true).put("durationMs",duration).put("positionBeforeMs",before).put("positionMs",position).put("videoWidth",width).put("videoHeight",height).put("isPlaying",playing).toString());
  }catch(Throwable e){Throwable cause=e instanceof InvocationTargetException?((InvocationTargetException)e).getCause():e;System.out.println("PLAYBACK FAIL "+cause.toString());System.exit(1);}finally{if(player!=null)type.getMethod("release").invoke(player);if(thread!=null)thread.getClass().getMethod("quitSafely").invoke(thread);NativeHttp.session().stop();}
 }
}
